from datetime import datetime, timedelta

current_time = datetime.fromisoformat('2023-05-18T11:58:00')
threshold_date = current_time - timedelta(days=40)

# Filter payment requests that are pending and 40+ days old
pending_requests = []
for req in payment_requests['payment_requests']:
    if req['status'] == 'pending':
        req_date = datetime.fromisoformat(req['created_at'])
        if req_date <= threshold_date:
            pending_requests.append(req)

print(f"Found {len(pending_requests)} payment requests that are 40+ days old and pending:")
for req in pending_requests:
    print(f"  - ID: {req['id']}, Amount: {req['amount']}, To: {req['to_user']}, Created: {req['created_at']}")

